"""Structure out of article-style HTML: headings, paragraphs, lists, tables, equations and references, for two sources that publish it through an official API:

  * MediaWiki `action=parse` output (Wikipedia), profile "mediawiki";
  * arXiv's own HTML papers (generated by LaTeXML), profile "latexml".

Standard library only (html.parser). The parser is tolerant: unknown markup is treated as inline text, a missing or odd structure never raises, and anything dropped
(navigation boxes, citation markers, hidden elements, styles, scripts) is dropped on purpose and counted. Nothing here is fetched or executed; the input is untrusted text.

Result (all plain JSON-able dicts so it can be cached and stored):
  {"title", "sections": [{"id", "heading", "level", "path", "anchor", "number", "paragraphs", "lists", "tables", "equations", "text"}], "references": [...], "warnings": [...]}
`sections[0]` is the lead (heading None). A section's `text` is what evidence extraction reads: paragraphs, list items and one sentence per table row, one per paragraph break."""
from __future__ import annotations

import re
from html.parser import HTMLParser
from typing import Any, Dict, List, Optional, Sequence, Tuple

from ..textkit import tokenize

VOID = frozenset("area base br col embed hr img input link meta param source track wbr".split())
ALWAYS_SKIP_TAGS = frozenset("style script noscript template head svg button select nav form iframe object audio video canvas".split())
HEADINGS = {f"h{i}": i for i in range(1, 7)}
BLOCK = frozenset("p div section article aside header footer main blockquote pre dl dt dd figure figcaption center address details summary".split())
MAX_TABLE_ROWS, MAX_TABLE_COLS, MAX_CELL, MAX_TABLES_PER_SECTION, MAX_REFERENCES = 80, 16, 180, 12, 60

EQUATION_TABLES = frozenset({"ltx_equation", "ltx_eqn_table", "ltx_equationgroup", "ltx_eqn_align"})
PROFILES: Dict[str, Dict[str, Any]] = {
    "mediawiki": {
        "skip_classes": frozenset("""reference mw-editsection navbox navbox-inner navbox-styles vertical-navbox sidebar sistersitebox noprint metadata hatnote ambox mbox-small mw-empty-elt
            thumb printfooter catlinks toc mw-jump-link shortdescription portal side-box authority-control navigation-not-searchable mw-cite-backlink cite-accessibility-label
            infobox-image mw-collapsible-toggle""".split()),
        "refs_classes": frozenset({"references"}),
        "stop_headings": frozenset(s.lower() for s in ("See also", "Notes", "References", "External links", "Further reading", "Bibliography", "Citations", "Footnotes")),
        "tex_wrapper": re.compile(r"^\{\\displaystyle\s*(.*)\}$", re.S),
    },
    "latexml": {
        "skip_classes": frozenset("""ltx_page_header ltx_page_footer ltx_role_navigation ltx_cite ltx_rdf ltx_pagination ltx_note_outer ltx_ERROR ltx_toc ltx_authors ltx_dates
            ltx_role_affiliation ltx_role_email ltx_eqn_eqno ltx_tag_bibitem""".split()),
        "refs_classes": frozenset({"ltx_biblist", "ltx_bibliography"}),
        "stop_headings": frozenset(),
        "tex_wrapper": None,
    },
}
NUMBERED = re.compile(r"^((?:\d+(?:\.\d+)*\.?|[IVX]+\.|[A-Z]\.|Appendix [A-Z])[   ]+)(?=\S)")


def _clean(text: str) -> str:
    return re.sub(r"\s+", " ", (text or "").replace(" ", " ").replace("​", "")).strip()


class _Table:
    def __init__(self, classes: frozenset) -> None:
        self.classes, self.caption, self.rows, self.row, self.cell, self.header_flags = classes, "", [], None, None, []
        self.in_caption = False
        self.row_headers: List[bool] = []


class ArticleParser(HTMLParser):
    def __init__(self, profile: str = "mediawiki") -> None:
        super().__init__(convert_charrefs=True)
        self.p = PROFILES[profile]
        self.profile = profile
        self.stack: List[Tuple[str, bool]] = []
        self.skipping = 0
        self.buf: List[str] = []
        self.sections: List[Dict[str, Any]] = [self._new_section(None, 0, [], None)]
        self.cur = self.sections[0]
        self.path: List[Tuple[int, str]] = []
        self.heading: Optional[Tuple[int, Optional[str], List[str]]] = None
        self.list_depth = 0
        self.items: List[List[str]] = []
        self.in_li = 0
        self.table: Optional[_Table] = None
        self.table_depth = 0
        self.refs_mode = 0
        self.refs_level = 0
        self.references: List[Dict[str, Any]] = []
        self.ref_buf: List[str] = []
        self.title = ""
        self.in_title = False
        self.last_section_id: Optional[str] = None
        self.pending_caption = ""
        self.stopped = False
        self.dropped = 0
        self.warnings: List[str] = []

    # ------------------------------------------------------------------ sections
    @staticmethod
    def _new_section(heading: Optional[str], level: int, path: List[str], anchor: Optional[str], number: Optional[str] = None) -> Dict[str, Any]:
        return {"id": "", "heading": heading, "level": level, "path": list(path), "anchor": anchor, "number": number, "paragraphs": [], "lists": [], "tables": [], "equations": [], "text": ""}

    def _text(self) -> str:
        out = _clean("".join(self.buf))
        self.buf.clear()
        return out

    def _flush_block(self) -> None:
        text = self._text()
        if not text or self.stopped or self.refs_mode or self.table is not None:
            return
        if self.in_title:
            self.title += (" " if self.title else "") + text
            return
        if self.in_li and self.items:
            self.items[-1].append(text)                                                         # text of a list item that is cut short by a nested list
            return
        if len(text) >= 2 and re.search(r"\w", text):
            self.cur["paragraphs"].append(text)

    def _open_section(self, level: int, heading: str, anchor: Optional[str]) -> None:
        number = None
        m = NUMBERED.match(heading)
        if m and self.profile == "latexml":
            number, heading = m.group(1).strip().rstrip("."), heading[m.end():].strip()
        while self.path and self.path[-1][0] >= level:
            self.path.pop()
        self.path.append((level, heading))
        self.stopped = heading.lower() in self.p["stop_headings"]
        sec = self._new_section(heading, level, [h for _, h in self.path], anchor or self.last_section_id, number)
        self.sections.append(sec)
        self.cur = sec

    # ------------------------------------------------------------------ events
    def _should_skip(self, tag: str, classes: frozenset, attrs: Dict[str, str]) -> bool:
        if tag in ALWAYS_SKIP_TAGS or "hidden" in attrs or attrs.get("aria-hidden") == "true" and "ltx_Math" not in classes:
            return True
        style = (attrs.get("style") or "").replace(" ", "").lower()
        if "display:none" in style and not any(c.startswith("mwe-math") for c in classes):
            return True
        return bool(classes & self.p["skip_classes"])

    def handle_starttag(self, tag: str, attrs_list: Sequence[Tuple[str, Optional[str]]]) -> None:
        attrs = {k: (v or "") for k, v in attrs_list}
        classes = frozenset(attrs.get("class", "").split())
        if self.skipping:
            if tag not in VOID:
                self.stack.append((tag, True))
                self.skipping += 1
            return
        if tag == "br":
            self.buf.append(" ")
            return
        if tag in VOID:
            return
        if self._should_skip(tag, classes, attrs):
            self.stack.append((tag, True))
            self.skipping += 1
            self.dropped += 1
            return
        if tag == "math":
            self._equation(attrs)
            self.stack.append((tag, True))                                                  # the MathML children are not text; the TeX in alttext is what we keep
            self.skipping += 1
            return
        self.stack.append((tag, False))
        if tag == "section" and attrs.get("id"):
            self.last_section_id = attrs["id"]
        if self.refs_mode:
            if tag == "li":
                self.buf.clear()
            return
        if tag in ("ul", "ol", "div", "section") and classes & self.p["refs_classes"]:
            self._flush_block()
            self.refs_mode, self.refs_level = 1, len(self.stack)                              # everything inside is the reference list until this element closes
            return
        if tag == "title" and not self.title:
            self.in_title = True
        if tag in HEADINGS and self.table is None:
            self._flush_block()
            self.heading = (HEADINGS[tag], attrs.get("id") or None, [])
            return
        if tag == "table" and not (classes & EQUATION_TABLES):
            self._start_table(classes)
            return
        if tag == "table":
            return                                                                              # a LaTeX display equation is laid out as a table: its maths is text, not data
        if self.table is not None:
            self._table_start(tag, attrs)
            return
        if tag in ("ul", "ol"):
            self._flush_block()
            self.list_depth += 1
            if self.list_depth == 1:
                self.items.append([])
            return
        if tag == "li":
            self._flush_block()
            self.in_li += 1
            return
        if tag in BLOCK or tag in ("p",):
            self._flush_block()

    def handle_endtag(self, tag: str) -> None:
        if tag in VOID:
            return
        i = next((k for k in range(len(self.stack) - 1, -1, -1) if self.stack[k][0] == tag), None)
        if i is None:
            return
        while len(self.stack) > i + 1:                                                      # close anything left open inside it
            t, skipped = self.stack.pop()
            if skipped:
                self.skipping -= 1
        _, skipped = self.stack.pop()
        if skipped:
            self.skipping -= 1
            return
        if self.skipping:
            return
        if self.refs_mode:
            if tag == "li":
                text = _clean("".join(self.buf))
                self.buf.clear()
                if text and len(self.references) < MAX_REFERENCES:
                    self.references.append({"text": text[:400]})
            if len(self.stack) < self.refs_level:
                self.refs_mode = 0
                self.buf.clear()
            return
        if tag in HEADINGS and self.heading is not None and HEADINGS[tag] == self.heading[0]:
            level, anchor, _ = self.heading
            text = re.sub(r"\[\s*edit\s*\]", "", self._text(), flags=re.I).strip()
            self.heading = None
            if text and level == 1 and not self.title:
                self.title = text
            elif text:
                self._open_section(level, text, anchor)
            return
        if tag == "title":
            self._flush_block()
            self.in_title = False
            return
        if tag == "table":
            self._end_table()                                                                    # a no-op for an equation laid out as a table (nothing was opened)
            return
        if self.table is not None:
            self._table_end(tag)
            return
        if tag == "figcaption":
            text = self._text()
            if text and not self.stopped:
                self.pending_caption = text[:200]
                self.cur["paragraphs"].append(text)
            return
        if tag == "li":
            text = self._text()
            self.in_li = max(0, self.in_li - 1)
            if text and not self.stopped and self.items:
                self.items[-1].append(text)
            return
        if tag in ("ul", "ol"):
            self._flush_block()
            self.list_depth = max(0, self.list_depth - 1)
            if self.list_depth == 0 and self.items:
                items = self.items.pop()
                if items and not self.stopped:
                    self.cur["lists"].append(items[:80])
            return
        if tag in BLOCK or tag == "p":
            self._flush_block()

    def handle_data(self, data: str) -> None:
        if self.skipping:
            return
        self.buf.append(data)

    # ------------------------------------------------------------------ equations
    def _equation(self, attrs: Dict[str, str]) -> None:
        tex = (attrs.get("alttext") or "").strip()
        wrap = self.p["tex_wrapper"]
        if wrap is not None:
            m = wrap.match(tex)
            if m:
                tex = m.group(1).strip()
        tex = _clean(tex)
        if not tex:
            return
        display = attrs.get("display") == "block"
        mark = f" $${tex}$$ " if display else f" ${tex}$ "
        if self.table is not None and self.table.cell is not None:
            self.table.cell.append(f"${tex}$")
        elif self.heading is None and not self.stopped:
            self.buf.append(mark)
            if len(self.cur["equations"]) < 60:
                self.cur["equations"].append({"tex": tex[:400], "display": display})

    # ------------------------------------------------------------------ tables
    def _start_table(self, classes: frozenset) -> None:
        self.table_depth += 1
        if self.table_depth == 1:
            self._flush_block()
            self.table = _Table(classes)
            self.table.caption, self.pending_caption = self.pending_caption, ""
            if self.table.caption and self.cur["paragraphs"] and self.cur["paragraphs"][-1].startswith(self.table.caption[:60]):
                self.cur["paragraphs"].pop()                                                  # the caption is kept with its table, not twice

    def _table_start(self, tag: str, attrs: Dict[str, str]) -> None:
        t = self.table
        assert t is not None
        if self.table_depth > 1:
            return
        if tag == "caption" or (tag == "figcaption"):
            t.in_caption = True
            self.buf.clear()
        elif tag == "tr":
            t.row, t.row_headers = [], []
        elif tag in ("td", "th") and t.row is not None:
            t.cell = []
            t.row_headers.append(tag == "th")
            self.buf.clear()
            try:
                span = max(1, min(int(attrs.get("colspan", "1") or 1), 6))
            except ValueError:
                span = 1
            t.cell_span = span                                                                # type: ignore[attr-defined]

    def _table_end(self, tag: str) -> None:
        t = self.table
        assert t is not None
        if self.table_depth > 1:
            return
        if tag in ("td", "th") and t.cell is not None and t.row is not None:
            text = _clean("".join(self.buf) + " " + " ".join(t.cell))
            self.buf.clear()
            for _ in range(getattr(t, "cell_span", 1)):
                if len(t.row) < MAX_TABLE_COLS:
                    t.row.append(text[:MAX_CELL])
            t.cell = None
        elif tag == "tr" and t.row is not None:
            if any(c for c in t.row) and len(t.rows) < MAX_TABLE_ROWS:
                t.rows.append(t.row)
                t.header_flags.append(all(t.row_headers) if t.row_headers else False)
            t.row = None
        elif tag in ("caption", "figcaption") and t.in_caption:
            t.caption = _clean("".join(self.buf))[:200]
            self.buf.clear()
            t.in_caption = False

    def _end_table(self) -> None:
        if self.table_depth == 0:
            return
        self.table_depth -= 1
        if self.table_depth > 0:
            return
        t, self.table = self.table, None
        self.buf.clear()
        if t is None or not t.rows or self.stopped:
            return
        kind = "infobox" if "infobox" in t.classes else "table"
        header_rows = 0
        if kind == "infobox":
            if not t.caption and len(t.rows[0]) == 1 or (len(t.rows[0]) >= 1 and len(set(t.rows[0])) == 1 and len(t.rows[0]) > 1):
                t.caption, t.rows = t.rows[0][0][:200], t.rows[1:]                             # the title row of an infobox names its subject
        else:
            for flag in t.header_flags:
                if flag:
                    header_rows += 1
                else:
                    break
        if not t.rows:
            return
        if kind == "table" and header_rows == 0 and len(t.rows) >= 2 and t.rows[0] and all(c and not re.search(r"\d", c) for c in t.rows[0]) and len(set(map(len, t.rows))) == 1:
            header_rows = 1                                                                    # a plain first row of non-numeric labels is treated as the header
        if len(self.cur["tables"]) < MAX_TABLES_PER_SECTION:
            self.cur["tables"].append({"caption": t.caption, "kind": kind, "header_rows": header_rows, "rows": t.rows, "sentences": table_sentences(t.caption, kind, header_rows, t.rows)})

    # ------------------------------------------------------------------ finish
    def finish(self) -> Dict[str, Any]:
        self.close()
        self._flush_block()
        for i, sec in enumerate(self.sections):
            sec["id"] = f"s{i}"
            sec["text"] = render_section(sec)
        if not any(s["text"] for s in self.sections):
            self.warnings.append("NO_TEXT")
        return {"title": self.title, "sections": [s for s in self.sections if s["text"] or s["heading"] is None], "references": self.references, "warnings": self.warnings, "dropped": self.dropped}


def table_sentences(caption: str, kind: str, header_rows: int, rows: List[List[str]]) -> List[str]:
    """One plain sentence per table row ("Column: value; Column: value."), so a row can be found, quoted and cited like any sentence."""
    out: List[str] = []
    headers = rows[header_rows - 1] if header_rows and header_rows <= len(rows) else None
    lead = f"{caption.rstrip('.:; ')}: " if caption else ""
    for row in rows[header_rows:]:
        cells = [c for c in row]
        if kind == "infobox" and len(cells) == 2 and cells[0] and cells[1]:
            body = f"{cells[0]}: {cells[1]}"
        elif headers and len(headers) == len(cells):
            pairs, seen = [], set()
            for h, v in zip(headers, cells):
                if v and (h, v) not in seen:
                    seen.add((h, v))
                    pairs.append(f"{h}: {v}" if h else v)
            body = "; ".join(pairs)
        else:
            body = "; ".join(c for c in cells if c)
        if body:
            out.append((lead + body).rstrip(".") + ".")
    return out


def render_section(sec: Dict[str, Any]) -> str:
    parts: List[str] = list(sec["paragraphs"])
    for items in sec["lists"]:
        parts += [i.rstrip(".;,") + "." if re.search(r"[A-Za-z0-9)]$", i) else i for i in items]
    for t in sec["tables"]:
        parts += t["sentences"]
    return "\n\n".join(p for p in parts if p)


def parse_article(markup: str, profile: str = "mediawiki") -> Dict[str, Any]:
    parser = ArticleParser(profile)
    try:
        parser.feed(markup or "")
    except Exception:  # noqa: BLE001 - html.parser is tolerant, but a pathological input must never break a research run
        parser.warnings.append("PARSE_INTERRUPTED")
    return parser.finish()


# ------------------------------------------------------------------ choosing what to read from a long article
def _score(section: Dict[str, Any], terms: Sequence[str]) -> float:
    head = set(tokenize(" ".join(section["path"]) if section["heading"] else ""))
    body = tokenize(section["text"])
    if not terms or not body:
        return 0.0
    counts: Dict[str, int] = {}
    for t in body:
        counts[t] = counts.get(t, 0) + 1
    length_norm = 1.0 / (1.0 + len(body) / 800.0)
    s = 0.0
    for t in terms:
        s += (counts.get(t, 0) ** 0.5) * length_norm + (2.5 if t in head else 0.0)
    covered = sum(1 for t in set(terms) if counts.get(t) or t in head)
    return s * (0.5 + covered / max(1, len(set(terms))))


def select_sections(article: Dict[str, Any], query: str, *, max_chars: int = 14000, max_sections: int = 7, lead_chars: int = 3500) -> List[Dict[str, Any]]:
    """The lead plus the sections that best match the question, in article order, within a size budget. A long article is never read whole into a prompt or a report."""
    terms = list(dict.fromkeys(tokenize(query)))
    secs = article["sections"]
    if not secs:
        return []
    lead = secs[0]
    ranked = sorted((s for s in secs[1:] if s["text"]), key=lambda s: (-_score(s, terms), s["id"]))
    chosen: List[Dict[str, Any]] = [lead] if lead["text"] else []
    used = min(len(lead["text"]), lead_chars)
    for s in ranked:
        if len(chosen) >= max_sections or _score(s, terms) <= 0:
            break
        size = len(s["text"])
        if used + min(size, 4000) > max_chars:
            continue
        chosen.append(s)
        used += min(size, 4000)
    order = {s["id"]: i for i, s in enumerate(secs)}
    chosen.sort(key=lambda s: order[s["id"]])
    return chosen


def compose(article: Dict[str, Any], chosen: Sequence[Dict[str, Any]], *, per_section: int = 4000, lead_chars: int = 3500) -> Tuple[str, List[Dict[str, Any]]]:
    """(text, offsets): the chosen sections joined by blank lines, and for each the exact character range it occupies, so a quoted sentence can be cited with its section."""
    text, offsets = "", []
    for s in chosen:
        body = s["text"][: (lead_chars if s["heading"] is None else per_section)]
        if len(body) < len(s["text"]):
            cut = max(body.rfind("\n\n"), body.rfind(". "))
            body = body[: cut + 1] if cut > len(body) // 2 else body
        if not body.strip():
            continue
        if text:
            text += "\n\n"
        start = len(text)
        text += body
        offsets.append({"id": s["id"], "heading": s["heading"], "path": s["path"], "anchor": s["anchor"], "number": s.get("number"), "start": start, "end": len(text)})
    return text, offsets


def section_at(offsets: Sequence[Dict[str, Any]], position: int) -> Optional[Dict[str, Any]]:
    for o in offsets:
        if o["start"] <= position < o["end"]:
            return o
    return None
